import{_ as s,a0 as l,w as r,s as d,ao as a,I as i,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150806 Linux FAQs with Answers--How to enable logging in Open vSwitch for debugging and troubleshooting","title":"Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障","tag":"201509","desc":""},"relativePath":"201509/20150806 Linux FAQs with Answers--How to enable logging in Open vSwitch for debugging and troubleshooting.md","filePath":"[post].md"}'),g={name:"201509/20150806 Linux FAQs with Answers--How to enable logging in Open vSwitch for debugging and troubleshooting.md"};function c(u,t,f,v,m,O){const o=l("Link");return r(),d("div",null,[t[13]||(t[13]=a(`<h1 id="linux有問必答-如何啓用open-vswitch的日誌功能以便調試和排障" tabindex="-1">Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障 <a class="header-anchor" href="#linux有問必答-如何啓用open-vswitch的日誌功能以便調試和排障" aria-label="Permalink to “Linux有問必答：如何啓用Open vSwitch的日誌功能以便調試和排障”">​</a></h1><blockquote><p><strong>問題</strong> 我試着為我的Open vSwitch部署排障，鑑於此，我想要檢查它的由內建日誌機制生成的調試信息。我怎樣才能啓用Open vSwitch的日誌功能，並且修改它的日誌等級（如，修改成INFO/DEBUG級別）以便於檢查更多詳細的調試信息呢？</p></blockquote><p>Open vSwitch（OVS)是Linux平台上最流行的開源的虛擬交換機。由於當今的數據中心日益依賴於軟件定義網絡（SDN）架構，OVS被作為數據中心的SDN部署中的事實標準上的網絡元素而得到飛速應用。</p><p>Open vSwitch具有一個內建的日誌機制，它稱之為VLOG。VLOG工具允許你在各種網絡交換組件中啓用並自定義日誌，由VLOG生成的日誌信息可以被髮送到一個控制台、syslog以及一個便於查看的單獨日誌文件。你可以通過一個名為<code>ovs-appctl</code>的命令列工具在運行時動態配置OVS日誌。</p><p><img src="https://farm1.staticflickr.com/499/19300367114_cd8aac2fb2_c.jpg" alt=""></p><p>這裏為你演示如何使用<code>ovs-appctl</code>啓用Open vSwitch中的日誌功能，並進行自定義。</p><p>下面是<code>ovs-appctl</code>自定義VLOG的語法。</p><pre><code>$ sudo ovs-appctl vlog/set module[:facility[:level]] 
</code></pre><ul><li><strong>Module</strong>：OVS中的任何合法組件的名稱（如netdev，ofproto，dpif，vswitchd等等）</li><li><strong>Facility</strong>：日誌信息的目的地（必須是：console，syslog，或者file）</li><li><strong>Level</strong>：日誌的詳細程度（必須是：emer，err，warn，info，或者dbg）</li></ul><p>在OVS源代碼中，模組名稱在源文件中是以以下格式定義的：</p><pre><code>VLOG_DEFINE_THIS_MODULE(&lt;module-name&gt;);
</code></pre><p>例如，在lib/netdev.c中，你可以看到：</p><pre><code>VLOG_DEFINE_THIS_MODULE(netdev);
</code></pre><p>這個表明，lib/netdev.c是netdev模組的一部分，任何在lib/netdev.c中生成的日誌信息將屬於netdev模組。</p><p>在OVS源代碼中，有多個嚴重度等級用於定義幾個不同類型的日誌信息：VLOG_INFO()用於報告，VLOG_WARN()用於警告，VLOG_ERR()用於錯誤提示，VLOG_DBG()用於調試信息，VLOG_EMERG用於緊急情況。日誌等級和工具確定哪個日誌信息發送到哪裏。</p><p>要查看可用模組、工具和各自日誌級別的完整列表，請運行以下命令。該命令必須在你啓動OVS後調用。</p><pre><code>$ sudo ovs-appctl vlog/list 
</code></pre><p><img src="https://farm1.staticflickr.com/465/19734939478_7eb5d44635_c.jpg" alt=""></p><p>輸出結果顯示了用於三個場合（facility：console，syslog，file）的各個模組的調試級別。默認情況下，所有模組的日誌等級都被設置為INFO。</p><p>指定任何一個OVS模組，你可以選擇性地修改任何特定場合的調試級別。例如，如果你想要在控制台屏幕中查看dpif更為詳細的調試信息，可以運行以下命令。</p><pre><code>$ sudo ovs-appctl vlog/set dpif:console:dbg 
</code></pre><p>你將看到dpif模組的console工具已經將其日誌等級修改為DBG，而其它兩個場合syslog和file的日誌級別仍然沒有改變。</p><p><img src="https://farm1.staticflickr.com/333/19896760146_5d851311ae_c.jpg" alt=""></p><p>如果你想要修改所有模組的日誌等級，你可以指定“ANY”作為模組名。例如，下面命令將修改每個模組的console的日誌級別為DBG。</p><pre><code>$ sudo ovs-appctl vlog/set ANY:console:dbg 
</code></pre><p><img src="https://farm1.staticflickr.com/351/19734939828_8c7f59e404_c.jpg" alt=""></p><p>同時，如果你想要一次性修改所有三個場合的日誌級別，你可以指定“ANY”作為場合名。例如，下面的命令將修改每個模組的所有場合的日誌級別為DBG。</p><pre><code>$ sudo ovs-appctl vlog/set ANY:ANY:dbg 
</code></pre><hr>`,29)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://ask.xmodulo.com/enable-logging-open-vswitch.html"},{default:p(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/enable-logging-open-vswitch.html",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),n(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:p(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(o,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const h=s(g,[["render",c]]);export{_ as __pageData,h as default};
